insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '27cb31a1-5427-4aa3-9c38-3998d3d6ccf6', 'dagegen', 'Die Unionsfraktion wollte die Mietpreisbremse nur bis 2029 verlängern und danach auslaufen lassen; eine Entfristung lehnte sie ab.', 'Bundestag, Drucksache 21/631 vom 25.06.2025, PDF-Seite 11 (Bericht des Rechtsausschusses, indirekte Rede)', null, 'https://dserver.bundestag.de/btd/21/006/2100631.pdf#page=11', 'Danach trete die Mietpreisbremse außer Kraft. Sie sei als befristetes Instrument konzipiert gewesen und bleibe dies auch.', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '82a589fb-b9bf-4a06-91d5-2eb2be2d0df4', 'dagegen', 'Die Unionsfraktion wollte die Mietpreisbremse nur bis 2029 verlängern und danach auslaufen lassen; eine Entfristung lehnte sie ab.', 'Bundestag, Drucksache 21/631 vom 25.06.2025, PDF-Seite 11 (Bericht des Rechtsausschusses, indirekte Rede)', null, 'https://dserver.bundestag.de/btd/21/006/2100631.pdf#page=11', 'Danach trete die Mietpreisbremse außer Kraft. Sie sei als befristetes Instrument konzipiert gewesen und bleibe dies auch.', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '32ad76bd-db22-420d-89c2-0ba593d4f289', 'dafuer', 'Will die Mietpreisbremse unbefristet gelten lassen und auf Wohnungen ausweiten, die bis 2019 bezogen wurden.', 'Wahlprogramm 2025', 20, null, 'Die Mietpreisbremse soll unbefristet und auch für Immobilien, die bis 2019 bezogen wurden, gelten, um langfristig für stabile und bezahlbare Mieten in angespannten Wohnungsmärkten zu sorgen. Wir werden dafür sorgen, dass die Mietpreisbremse nicht durch zum Beispiel (teil-)möblierte und befristete Wohnungsangebote umgangen werden kann.', 'Mietpreisbremse entfristen, auf Wohnungen mit Erstbezug bis 2019 ausweiten und Umgehung über möblierte oder befristete Vermietung unterbinden.', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '88c662bc-56a3-47e1-a72f-9bd13342e487', 'dafuer', 'Wollen die Mietpreisbremse verlängern und durch den Wegfall von Ausnahmen verschärfen.', 'Wahlprogramm 2025', 69, null, 'Wir werden die Mietpreisbremse verlängern und sie durch die Abschaffung von Ausnahmen verschärfen. Wir wollen die Mietpreisbremse außerdem bereits auf Wohnungen anwenden, die älter als fünf Jahre sind.', 'Ausnahmen streichen und die Bremse auf Wohnungen anwenden, die älter als fünf Jahre sind.', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '605a6b11-ae88-41f0-af95-ed4c457aac32', 'dagegen', 'Hält die Mietpreisbremse für ein Investitionshemmnis und will sie auslaufen lassen.', 'Wahlprogramm 2025, gedruckte Seite 43', 44, null, 'Die Mietpreisbremse ist nachweislich eine Investitionsbremse. Deshalb lassen wir sie auslaufen.', 'Mietpreisbremse auslaufen lassen.', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '9823eced-6ef4-485f-a509-dd754f98f4ba', 'dagegen', 'Lehnt die Mietpreisbremse als staatliche Überregulierung und Investitionshemmnis ab.', 'Wahlprogramm 2025, gedruckte Seite 38', 39, null, 'Die AfD steht für ein ausgewogenes Mietrecht und lehnt staatliche Überregulierungen sowie Investitionshemmnisse wie die Mietpreisbremse oder den Mietendeckel ab.', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', 'e257cff5-1d3a-472e-99f9-2b8a28ee9f70', 'dafuer', 'Will die Mietpreisbremse entfristen, flächendeckend gelten lassen und verschärfen, zusätzlich zu einem Mietenstopp.', 'Antrag der Bundestagsfraktion Die Linke, Drucksache 21/355 vom 03.06.2025, PDF-Seite 2', null, 'https://dserver.bundestag.de/btd/21/003/2100355.pdf#page=2', '1. die bisherige Mietpreisbremse nachgeschärft wird, sodass a) die Mietpreisbremse entfristet wird und flächendeckend gilt;', 'Bundesweiter Mietendeckel und als Sofortmaßnahme Ausschluss von Mieterhöhungen für sechs Jahre.', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', 'f7d4cb3d-ef85-442c-9a9f-f7ed9609984e', 'dagegen', 'Will die Mietpreisbremse durch eine strengere Regel ersetzen, einen bundesweiten Mietendeckel. Das „dagegen“ heißt hier: mehr Regulierung, nicht weniger.', 'Wahlprogramm 2025', 28, null, 'Wir fordern einen bundesweiten Mietendeckel statt einer wirkungslosen Mietpreisbremse.', 'Mietendeckel statt Mietpreisbremse; Mieten in überteuerten Regionen bis Ende des Jahrzehnts einfrieren.', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', 'a2bbca41-0896-4a23-9a83-5c77b8ce9f4b', 'dagegen', 'Lehnte im Wahl-O-Mat 2025 eine weitere gesetzliche Begrenzung der Mieten bei Neuvermietung ab und setzt auf Wohnungsbau und Bürgeranleihen.', 'Wahl-O-Mat zur Bundestagswahl 2025 (bpb), These 6 „Begrenzung der Mietpreise“, Antwort: stimme nicht zu', null, 'https://www.wahl-o-mat.de/bundestagswahl2025/app/main_app.html', 'Statt für einen investitionsfeindlichen Mietendeckel stehen wir für zweckgebundene Bürgeranleihen nach Münchener Vorbild.', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', 'e338320e-ac96-4322-b022-3ccc0f3fe507', 'dafuer', 'Unterstützt die Weiterführung der Mietpreisbremse.', 'Wahl-O-Mat zur Bundestagswahl 2025 (bpb), These 6 „Begrenzung der Mietpreise“, Antwort: stimme zu', null, 'https://www.wahl-o-mat.de/bundestagswahl2025/app/main_app.html', 'Als SSW unterstützen wir darum auch die Forderungen zur Weiterführung der Mietpreisbremse und des bundesweiten Mietendeckels.', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', 'aa5e822f-271e-450d-84b2-4e528204e30a', 'dafuer', 'Stimmte im Wahl-O-Mat 2025 zu, dass Mieten bei Neuvermietung weiterhin gesetzlich begrenzt werden sollen.', 'Wahl-O-Mat zur Bundestagswahl 2025 (bpb), These 6 „Begrenzung der Mietpreise“, Antwort: stimme zu', null, 'https://www.wahl-o-mat.de/bundestagswahl2025/app/main_app.html', 'Volts Lösung für ein Recht auf bezahlbaren Wohnraum ist dessen Verankerung im Grundgesetz und die damit einhergehende Verpflichtung zu reglementierten Mieten, unteranderem durch Sozialbindung und mehr genossenschaftliche und kommunale Trägerschaften.', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', '27cb31a1-5427-4aa3-9c38-3998d3d6ccf6', 'dagegen', 'Die Unionsfraktion will den nationalen CO2-Preis 2027 einfrieren, statt ihn steigen zu lassen.', 'Bundestag, Drucksache 21/8626 vom 14.10.2026, PDF-Seite 20 (Bericht des Umweltausschusses, indirekte Rede, Vorabfassung)', null, 'https://dserver.bundestag.de/btd/21/086/2108626.pdf#page=20', 'Die Fraktion der CDU/CSU erklärte, mit der Gesetzesänderung die Zusage einzuhalten, den nationalen CO₂Preis im kommenden Jahr einzufrieren.', 'CO2-Preis 2027 einfrieren (Drittes Gesetz zur Änderung des Brennstoffemissionshandelsgesetzes).', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', '82a589fb-b9bf-4a06-91d5-2eb2be2d0df4', 'dagegen', 'Die Unionsfraktion will den nationalen CO2-Preis 2027 einfrieren, statt ihn steigen zu lassen.', 'Bundestag, Drucksache 21/8626 vom 14.10.2026, PDF-Seite 20 (Bericht des Umweltausschusses, indirekte Rede, Vorabfassung)', null, 'https://dserver.bundestag.de/btd/21/086/2108626.pdf#page=20', 'Die Fraktion der CDU/CSU erklärte, mit der Gesetzesänderung die Zusage einzuhalten, den nationalen CO₂Preis im kommenden Jahr einzufrieren.', 'CO2-Preis 2027 einfrieren (Drittes Gesetz zur Änderung des Brennstoffemissionshandelsgesetzes).', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', '32ad76bd-db22-420d-89c2-0ba593d4f289', 'dagegen', 'Hält am beschlossenen Preispfad fest und sieht den CO2-Preis für Haushalte nur als ergänzendes Instrument.', 'Wahlprogramm 2025', 33, null, 'Ein Preis auf den Ausstoß von CO2 für private Haushalte und kleine Unternehmen kann für uns immer nur ein ergänzendes Instrument sein. Der bereits gesetzlich beschlossene CO2-Preis pro Tonne von 55 Euro in 2025 und maximal 65 Euro in 2026 gilt.', 'Entlastung etwa durch ein Klimageld ab 2027.', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', '9823eced-6ef4-485f-a509-dd754f98f4ba', 'dagegen', 'Will die CO2-Abgaben ersatzlos abschaffen.', 'Wahlprogramm 2025, gedruckte Seite 57', 58, null, 'Wir fordern eine ersatzlose Abschaffung der CO₂-Abgaben.', 'CO2-Abgaben abschaffen.', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', 'e257cff5-1d3a-472e-99f9-2b8a28ee9f70', 'dagegen', 'Lehnt einen CO2-Preis über den Emissionshandel für Wärme und Verkehr ab und will dort stattdessen feste Emissionsgrenzen.', 'Wahlprogramm 2025', 33, null, 'Wir lehnen den Emissionshandel in den Sektoren Wärme und Verkehr (ETS-2) ab: Stattdessen müssen verbindliche Klimaziele und Emissionsgrenzen gesetzt werden.', 'Soziales Klimageld von 320 Euro pro Person und Jahr (S. 7).', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', 'f7d4cb3d-ef85-442c-9a9f-f7ed9609984e', 'dagegen', 'Will den CO2-Preis abschaffen.', 'Wahlprogramm 2025', 10, null, 'Den CO2-Preis, der alles teurer macht, ohne dass es für die meisten Menschen Alternativen gibt, wollen wir abschaffen.', 'CO2-Preis abschaffen; EU-Emissionshandel globalisieren oder abschaffen (S. 11).', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', '27cb31a1-5427-4aa3-9c38-3998d3d6ccf6', 'dagegen', 'Hält an der geltenden Regelung fest, also an der Rente mit 67 ab 2031, ohne weitere Anhebung.', 'Gemeinsames Wahlprogramm von CDU und CSU 2025, gedruckte Seite 32', 34, null, 'An der bestehenden gesetzlichen Regelung zum Renteneintrittsalter halten wir fest. Die Regelung für besonders langjährige Versicherte mit 45 Versicherungsjahren behalten wir mit Blick auf die Planungssicherheit für Unternehmen und rentennahe Jahrgänge bei.', 'Aktivrente für freiwilliges Weiterarbeiten (S. 33).', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', '82a589fb-b9bf-4a06-91d5-2eb2be2d0df4', 'dagegen', 'Hält an der geltenden Regelung fest, also an der Rente mit 67 ab 2031, ohne weitere Anhebung.', 'Gemeinsames Wahlprogramm von CDU und CSU 2025, gedruckte Seite 32', 34, null, 'An der bestehenden gesetzlichen Regelung zum Renteneintrittsalter halten wir fest. Die Regelung für besonders langjährige Versicherte mit 45 Versicherungsjahren behalten wir mit Blick auf die Planungssicherheit für Unternehmen und rentennahe Jahrgänge bei.', 'Aktivrente für freiwilliges Weiterarbeiten (S. 33).', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', '32ad76bd-db22-420d-89c2-0ba593d4f289', 'dagegen', 'Lehnt eine Anhebung der Regelaltersgrenze ab.', 'Wahlprogramm 2025', 25, null, 'Das haben sich gerade Menschen verdient, die früh begonnen haben zu arbeiten. Eine Anhebung der Regelaltersgrenze lehnen wir ab.', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', '88c662bc-56a3-47e1-a72f-9bd13342e487', 'dagegen', 'Halten an der Rente mit 67 fest und wollen freiwilliges längeres Arbeiten erleichtern.', 'Wahlprogramm 2025', 98, null, 'Wir halten an der Rente mit 67 fest. Aber wir schaffen Anreize und machen es den Menschen leichter, länger zu arbeiten, wenn sie dies wollen, auch über die Regelaltersgrenze hinaus.', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', '9823eced-6ef4-485f-a509-dd754f98f4ba', 'dagegen', 'Die AfD-Fraktion lehnt eine Anhebung der Regelaltersgrenze über 67 Jahre hinaus ab.', 'Antrag der AfD-Bundestagsfraktion, Drucksache 21/2165 vom 13.10.2025, PDF-Seite 1', null, 'https://dserver.bundestag.de/btd/21/021/2102165.pdf#page=1', 'Der Deutsche Bundestag lehnt eine weitere Anhebung der Regelaltersgrenze über das 67. Lebensjahr hinaus ab und fordert verbesserte Möglichkeiten für einen abschlagsfreien Rentenzugang in Abhängigkeit von der Beitragsleistung.', 'Abschlagsfreie Rente nach 45 Arbeitsjahren.', 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
