insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('0a0132a5-e202-4437-8818-312bca25c007', 'e257cff5-1d3a-472e-99f9-2b8a28ee9f70', 'dafuer', 'Will Beamte, Selbstständige und Abgeordnete in eine gemeinsame Erwerbstätigenversicherung einbeziehen.', 'Wahlprogramm 2025', 15, null, 'Für ein gerechtes Rentensystem zahlen alle Menschen mit Erwerbseinkommen – auch Beamt*innen, Selbstständige, Freiberufler*innen, Manager*innen und Abgeordnete – in eine solidarische Erwerbstätigenversicherung ein.', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('0a0132a5-e202-4437-8818-312bca25c007', 'aa5e822f-271e-450d-84b2-4e528204e30a', 'dafuer', 'Will Verbeamtete, Selbstständige und Freischaffende schrittweise in die gesetzliche Rentenversicherung integrieren.', 'Wahlprogramm 2025', 92, null, 'Verbeamtete Personen, Selbstständige und Freischaffende werden schrittweise in das Rentensystem integriert,', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('0a0132a5-e202-4437-8818-312bca25c007', 'f7d4cb3d-ef85-442c-9a9f-f7ed9609984e', 'dafuer', 'Will Beamte, Abgeordnete und Minister verpflichtend in die gesetzliche Rente einzahlen lassen.', 'Wahlprogramm 2025', 23, null, 'alle Erwerbstätigen, auch alle Bundestagsabgeordneten und Bundesminister, verpflichtend in die gesetzliche Rente einzahlen.', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
  values ('0a0132a5-e202-4437-8818-312bca25c007', '32ad76bd-db22-420d-89c2-0ba593d4f289', 'dafuer', 'Will zunächst alle Selbstständigen absichern und langfristig alle Erwerbstätigen einbeziehen.', 'Wahlprogramm 2025', 25, null, 'und langfristig alle Erwerbstätigen in die Solidarität der gesetzlichen Rentenversicherung einbeziehen. Wir wollen zunächst alle Selbstständigen absichern, die oft ein hohes Schutzbedürfnis haben.', null, 'veroeffentlicht', 'agent', 'maschinell');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, quelle_url, auszug, aenderung, status, erstellt_von, geprueft)
